// in cmd/get/get_new_resource.go
package get

import (
    "github.com/spf13/cobra"
    "openhue-cli/openhue"
    "openhue-cli/util"
)

const (
    docShortGetNewResource = "Get new resource"
    docLongGetNewResource  = `
Fetches and displays all available new resources
`
    docExampleGetNewResource = `
# List all new resources
openhue get newresource
`
)

type NewResourceOptions struct {
    *CmdGetOptions
    Filter string
}

// NewCmdGetNewResource returns initialized Command instance for the 'get newresource' command
func NewCmdGetNewResource(ctx *openhue.Context, co *CmdGetOptions) *cobra.Command {
    o := NewResourceOptions{
        CmdGetOptions: co,
    }

    cmd := &cobra.Command{
        Use:     "newresource [id]",
        Aliases: []string{"newresources"},
        Short:   docShortGetNewResource,
        Long:    docLongGetNewResource,
        Example: docExampleGetNewResource,
        Args:    cobra.RangeArgs(0, 1),
        Run: func(cmd *cobra.Command, args []string) {
            o.RunGetNewResourceCmd(ctx, args)
        },
    }

    cmd.Flags().StringVarP(&o.Filter, "filter", "f", "", "Filter resources by property")

    return cmd
}

func (o *NewResourceOptions) RunGetNewResourceCmd(ctx *openhue.Context, args []string) {
    // Implementation
}

