func TestNewCmdGetResource(t *testing.T) {
    ctx, out := openhue.NewTestContext(nil)
    cmd := NewCmdGetResource(ctx, &CmdGetOptions{})

    assert.ThatCmdUseIs(t, cmd, "resource [id]")
    assert.NotNil(t, cmd.Run)
}


